<?php
declare(strict_types=1);require_once __DIR__.'/config/purchase_step14.php';$error=null;$type=(string)($_GET['type']??'bills');$allowed=['bills','suppliers','receipts','payments','returns'];if(!in_array($type,$allowed,true))$type='bills';$rows=[];$headers=[];$title='';
try{$pdo=business_db();purchase_step14_ensure($pdo);$ctx=purchase_step14_context($pdo);$orgId=(int)$ctx['organization_id'];if($type==='bills'){$title='Supplier Bills';$headers=['Invoice','Supplier','Invoice Date','Due Date','Total','Return Credit','Paid','Outstanding','Receipt Status','Payment Status','Status'];foreach(purchase_step14_bill_rows($pdo,$orgId,'all') as $b){$st=purchase_step14_recalc_bill($pdo,$orgId,(int)$b['id']);$rows[]=[$b['invoice_number'],$b['supplier_name'],$b['invoice_date'],$b['due_date'],$st['total'],$st['return_credit'],$st['paid'],$st['outstanding'],$st['receipt_status'],$st['payment_status'],$b['status']];}}elseif($type==='suppliers'){$title='Suppliers';$headers=['Code','Supplier','Contact','Mobile','Email','GSTIN','Terms Days','Billed','Returns','Paid','Outstanding','Status'];foreach(purchase_step14_suppliers($pdo,$orgId) as $s)$rows[]=[$s['supplier_code'],$s['supplier_name'],$s['contact_person'],$s['mobile'],$s['email'],$s['gstin'],$s['payment_terms_days'],$s['billed'],$s['return_credit'],$s['paid'],$s['outstanding'],$s['status']];}elseif($type==='receipts'){$title='Goods Receipts';$headers=['Receipt No','Date','Supplier','Invoice','Delivery Ref','Items','Quantity','Status'];foreach(purchase_step14_receipt_rows($pdo,$orgId) as $r)$rows[]=[$r['receipt_number'],$r['receipt_date'],$r['supplier_name'],$r['invoice_number'],$r['delivery_reference'],$r['item_count'],$r['total_qty'],$r['status']];}elseif($type==='payments'){$title='Supplier Payments';$headers=['Payment ID','Date','Supplier','Invoice','Amount','Method','Reference','Status'];$stmt=$pdo->prepare("SELECT p.*,s.supplier_name,b.invoice_number FROM purchase_payments p JOIN purchase_suppliers s ON s.id=p.supplier_id AND s.organization_id=p.organization_id JOIN purchase_bills b ON b.id=p.purchase_bill_id AND b.organization_id=p.organization_id WHERE p.organization_id=? ORDER BY p.payment_date DESC,p.id DESC");$stmt->execute([$orgId]);foreach($stmt->fetchAll() as $p)$rows[]=[(int)$p['id'],$p['payment_date'],$p['supplier_name'],$p['invoice_number'],$p['amount'],$p['payment_method'],$p['reference_no'],$p['status']];}else{$title='Purchase Returns';$headers=['Return No','Date','Supplier','Invoice','Credit','Reason','Status'];foreach(purchase_step14_return_rows($pdo,$orgId) as $r)$rows[]=[$r['return_number'],$r['return_date'],$r['supplier_name'],$r['invoice_number'],$r['total_credit'],$r['reason'],$r['status']];}
if(($_GET['download']??'')==='csv'){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="purchase-'.preg_replace('/[^a-z0-9_-]+/i','-',$type).'-'.date('Ymd').'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');fputcsv($out,$headers);foreach($rows as $r)fputcsv($out,$r);fclose($out);exit;}}catch(Throwable $e){$error=$e->getMessage();}
function pex_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Purchase Export - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><style>@media print{.os-topbar,.os-sidebar,.pex-actions{display:none!important}.os-layout{display:block}.os-main{padding:0}.os-card{box-shadow:none;border:0}}</style></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="purchase_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 14 • Purchase Export</small></span></a><div class="os-top-actions"><a class="os-btn" href="purchase_analytics.php">Analytics</a><a class="os-btn primary" href="purchase_center.php">Purchase Center</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Export</div><nav class="os-nav"><?php foreach(['bills'=>'Bills','suppliers'=>'Suppliers','receipts'=>'Receipts','payments'=>'Payments','returns'=>'Returns'] as $k=>$v):?><a class="<?= $type===$k?'active':'' ?>" href="?type=<?= pex_h($k) ?>"><i class="dot"></i><?= pex_h($v) ?></a><?php endforeach;?></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 14H • EXPORT</div><h1><?= pex_h($title) ?></h1><p>Exported rows use the same reconciled purchase data shown in the live workspaces.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'EXPORT READY':'Review required' ?></span><span class="os-chip"><?= count($rows) ?> rows</span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Export diagnostic:</strong> <?= pex_h($error) ?></div><?php else:?><div class="pex-actions" style="display:flex;gap:8px;margin:14px 0"><a class="os-btn primary" href="?type=<?= pex_h($type) ?>&download=csv">Download CSV</a><button class="os-btn" onclick="window.print()">Print / Save PDF</button></div><section class="os-card"><div class="pp-table-wrap"><table class="pp-table"><thead><tr><?php foreach($headers as $h):?><th><?= pex_h($h) ?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?= pex_h($v??'') ?></td><?php endforeach;?></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="<?= count($headers) ?>">No rows to export yet.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?><div class="os-footer-note"><strong>Export rule:</strong> CSV is UTF-8 and Print uses the current reconciled data; no hidden purchase values are invented.</div></main></div></body></html>